if type(previous)=='table' and type(previous.shutdown)=='function' then previous.shutdown() end
if type(previous)=='table' and type(previous._take_cleanup)=='function' then lifecycle.adopt_cleanup(previous._take_cleanup()) end

local local_player
local debounce_time = nil
local debounce_timeout = 1
local keybind_data = type(previous)=='table' and previous._keybind_data or checkbox:new(false, get_hash(plugin_label .. '_keybind_data'))
if PERSISTENT_MODE ~= nil and PERSISTENT_MODE ~= false then
    gui.elements.keybind_toggle:set(keybind_data:get())
