-- --- Plugin Control ---
AlfredTheButlerPlugin.enable = function()
    if not active then return false end
    gui.elements.main_toggle:set(true)
    gui.elements.keybind_toggle:set(true)
    settings:update_settings()
    return true
end
AlfredTheButlerPlugin.disable = function()
    if not active then return false end
    gui.elements.main_toggle:set(false)
    gui.elements.keybind_toggle:set(false)
    settings:update_settings()
    if lifecycle.busy() then lifecycle.cancel('Rosie town service disabled during service') end
    return true
end
AlfredTheButlerPlugin.shutdown = function()
    active=false
    lifecycle.retire()
    return true
end

-- --- Stash Pull Queue ---
-- Queue all matching unlocked stash copies for the next explicitly requested town run.
-- sno_id : number  — item SNO ID
-- action : string  — 'salvage' | 'sell'
-- returns true on success, false if args are invalid
AlfredTheButlerPlugin.queue_stash_pull = function(sno_id, action)
    if not active or lifecycle.busy() or type(sno_id) ~= 'number' or sno_id<=0 or sno_id==math.huge or sno_id~=math.floor(sno_id) then return false end
    if action ~= 'salvage' and action ~= 'sell' then return false end
    for _,entry in ipairs(tracker.pending_pulls) do if entry.sno_id==sno_id then return false end end
    table.insert(tracker.pending_pulls, { sno_id = sno_id, action = action })
    return true
end
AlfredTheButlerPlugin.get_pending_pulls = function()
    local copy={}
    for i,entry in ipairs(tracker.pending_pulls) do copy[i]={sno_id=entry.sno_id,action=entry.action} end
    return copy
end
AlfredTheButlerPlugin.clear_pending_pulls = function()
    if not active or lifecycle.busy() then return false end
    tracker.pending_pulls = {}
    return true
end
